{
  "extends": "../../tsconfig.base.json",
  "compilerOptions": {
    "composite": true,
    "module": "Preserve",
    "moduleResolution": "Bundler",
    "erasableSyntaxOnly": false,
    "verbatimModuleSyntax": false,
    "jsx": "react-jsx",
    "lib": ["ES2023", "ESNext.Disposable", "DOM", "DOM.Iterable"],
    "paths": {
      "~/*": ["./src/components/*"]
    },
    "plugins": [
      {
        "name": "@effect/language-service",
        // Diagnostic severities are deep-merged with tsconfig.base.json; list only web-specific overrides here.
        "diagnosticSeverity": {
          "globalDate": "off",
          "globalConsole": "off",
          "globalRandom": "off",
          "globalTimers": "off",
          "globalFetch": "off"
        }
      }
    ]
  },
  "include": [
    "src",
    "vite",
    "vite.config.ts",
    "vercel.ts",
    "test",
    "scripts/verify-built-boot.ts",
    "scripts/warm-dep-cache.ts",
    "../../scripts/lib/public-config.ts",
    "../../scripts/lib/third-party-licenses.ts"
  ]
}
